#!/usr/bin/env python3
"""Dependency-free static build. Run from any directory with Python 3."""
from pathlib import Path
from html import escape as esc
from urllib.parse import quote
import json

ROOT = Path(__file__).resolve().parents[1]
DIST = ROOT / 'dist'
ARTICLES = json.loads((ROOT / 'content/articles.json').read_text())
SITE = json.loads((ROOT / 'content/site.json').read_text())
EMAIL = 'sarah_harry@gettravelwithsarah.com'
ARROW = '<span aria-hidden="true" class="arrow">↗</span>'
ROUTES = []

def button(label='Start Planning', href='/plan-your-trip/', light=False):
    return f'<a class="button {"light" if light else ""}" href="{href}">{label}{ARROW}</a>'

def link(label, href):
    return f'<a class="text-link" href="{href}">{label}<span aria-hidden="true">↗</span></a>'

def image(name, alt, cls='', eager=False, sizes='(max-width: 600px) 100vw, 50vw'):
    paths = sorted((DIST / 'assets').glob(name + '-*.webp'), key=lambda p: int(p.stem.rsplit('-',1)[1]))
    src = f'/assets/{paths[-1].name}' if paths else f'/assets/{name}.webp'
    srcset = ' srcset="' + ', '.join(f'/assets/{p.name} {p.stem.rsplit("-",1)[1]}w' for p in paths) + '"' if paths else ''
    from_dimensions = {'italy':(1800,2397),'disney':(1000,1500),'cruise':(1200,900),'family':(900,898),'sarah':(206,206)}
    w,h = from_dimensions.get(name,(900,600))
    return f'<img class="{cls}" src="{src}"{srcset} sizes="{sizes}" width="{w}" height="{h}" alt="{esc(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=\"high\"" if eager else ""}>'

def header(route):
    def nav(label, href):
        current = ' aria-current="page"' if route == href else ''
        return f'<a href="{href}"{current}>{label}</a>'
    destinations = nav('Disney inspiration','/disney-trips/') + nav('Cruise inspiration','/cruises/') + nav('Italy & Europe','/italy-europe/')
    return f'''<a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner">
    <a class="wordmark" href="/" aria-label="Travel With Sarah home"><strong>Travel With Sarah</strong><span>Personal travel planning</span></a>
    <nav class="nav" aria-label="Main navigation">{nav('Home','/')}<details class="dest-menu"><summary>Travel Inspiration</summary><div class="dest-links">{destinations}</div></details>{nav('About Sarah','/about/')}{nav('Journal','/blog/')}</nav>
    {button()}<button type="button" class="menu-toggle" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open menu"><span class="menu-icon" aria-hidden="true">☰</span> Menu</button></div>
    <nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" hidden>{nav('Home','/')}{destinations}{nav('About Sarah','/about/')}{nav('Travel Journal','/blog/')}{nav('Contact & FAQs','/contact/')}{nav('Plan Your Trip','/plan-your-trip/')}</nav></header>'''

def footer():
    return f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><a class="wordmark" href="/"><strong>Travel With Sarah</strong><span>Personal travel planning</span></a><p>Ideas worth exploring. Adventures worth sharing. A conversation with Sarah is a lovely place to begin.</p><p>Sarah Harry · Based in Iowa<br>Independent travel consultant through Archer Travel.</p></div>
    <div><h3>Explore</h3><nav aria-label="Travel inspiration footer"><a href="/disney-trips/">Disney inspiration</a><a href="/cruises/">Cruise inspiration</a><a href="/italy-europe/">Italy & Europe</a><a href="/blog/">Travel Journal</a></nav></div>
    <div><h3>Get to know Sarah</h3><nav aria-label="Information footer"><a href="/about/">About Sarah</a><a href="/contact/">Contact & FAQs</a><a href="/plan-your-trip/">Plan Your Trip</a></nav></div>
    <div class="footer-contact"><h3>Let’s talk travel</h3><p><a class="contact-email" href="mailto:{EMAIL}">{EMAIL}</a><br><a href="tel:+15636908606">(563) 690-8606</a></p><nav aria-label="Social links"><a href="https://www.facebook.com/profile.php?id=61594135268016">Facebook ↗</a><a href="https://x.com/GetGuideSHarry">X ↗</a></nav></div></div>
    <div class="footer-bottom"><span>© 2026 Travel With Sarah. All rights reserved.</span><span>Small ideas. Beautiful possibilities.</span></div></div></footer>'''

def cta(title='Your next trip starts with an idea.', text='Share yours with Sarah, and take the first step toward planning it.'):
    return f'<section class="final-cta" aria-label="Start planning"><div class="wrap"><div><h2>{title}</h2><p>{text}</p></div>{button()}</div></section>'

def page(route, title, description, content, kind='WebPage'):
    path = DIST / (route.strip('/') + '/index.html' if route != '/' else 'index.html')
    path.parent.mkdir(parents=True, exist_ok=True)
    canonical = SITE['canonical_origin'].rstrip('/') + (route.rstrip('/') if route != '/' else '/')
    schema = {'@context':'https://schema.org','@type':kind,'name':title,'url':canonical,'isPartOf':{'@type':'WebSite','name':'Travel With Sarah','url':SITE['canonical_origin']},'inLanguage':'en-US'}
    robots = '<meta name="robots" content="noindex, nofollow">' if SITE['review_mode'] else '<meta name="robots" content="index, follow">'
    html = f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | Travel With Sarah</title><meta name="description" content="{esc(description,quote=True)}">{robots}<link rel="canonical" href="{canonical}"><meta name="theme-color" content="#244A4B"><meta property="og:title" content="{esc(title,quote=True)} | Travel With Sarah"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{SITE['canonical_origin']}/assets/italy-1200.webp"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/font-5.woff" as="font" type="font/woff" crossorigin><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body>{header(route)}<main id="main">{content}</main>{footer()}</body></html>'''
    path.write_text(html)
    ROUTES.append(route)

def journal_cards():
    excerpts = {'essential-packing-tips-for-your-next-adventure':('Travel essentials','packing','A thoughtful packing list, the right luggage, and a little room for the unexpected.'),'top-10-must-see-destinations-for-travelers':('Destination ideas','destinations','Find a little inspiration for the places that might belong on your next itinerary.'),'how-to-travel-on-a-budget-tips-and-tricks':('Travel budget','budget','Practical starting points for thinking about your trip and what you want to spend.')}
    cards = []
    for a in ARTICLES:
        category, key, text = excerpts[a['slug']]
        cards.append(f'''<article class="journal-card" data-category="{key}"><a href="/post/{a['slug']}/">{image(a['slug'],{'packing':'A suitcase neatly arranged with travel essentials','destinations':'Travel destination scene from Sarah’s original article','budget':'Travel scene from Sarah’s original budget article'}[key])}<span class="eyebrow">{category}</span><h3>{esc(a['title'])}</h3></a><p>{text}</p><a class="read" href="/post/{a['slug']}/" aria-label="Read {esc(a['title'],quote=True)}">Read the story <span aria-hidden="true">↗</span></a></article>''')
    return ''.join(cards)

def home():
    content = f'''<section class="hero" aria-labelledby="hero-title">{image('italy','The coast of Positano, Italy, overlooking the Mediterranean','hero-image',True,'100vw')}<div class="wrap"><div class="hero-copy"><span class="eyebrow">Personal travel planning</span><h1 id="hero-title">A trip to look forward to.<br><em>A plan that feels like you.</em></h1><p>Every great trip starts with an idea. Share the places, people, and little moments you have in mind with Sarah.</p><div class="hero-actions">{button('Plan My Trip','/plan-your-trip/',True)}{link('Explore travel inspiration','#inspiration')}</div></div></div><span class="hero-bottom">A little inspiration for your next chapter</span><span class="photo-note">POSITANO, ITALY</span></section>
    <div class="intro-strip"><div class="wrap"><p>The world is full of possibilities. Let’s find yours.</p><p>Sarah Harry <span class="dot"></span> Based in Iowa <span class="dot"></span> Archer Travel consultant</p></div></div>
    <section id="inspiration" class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Where will your idea take you?</span><h2>Some places stay with you.</h2></div><p>Family magic, open water, or an unhurried afternoon in Italy. Explore a few of the travel themes Sarah shares.</p></div>
    <div class="inspiration"><article class="feature large"><a href="/italy-europe/">{image('italy','Colorful buildings and blue water along the Italian coast')}<div class="caption"><span class="eyebrow">The art of slowing down</span><h3>Italy & Europe</h3><p>Coastal afternoons. Winding streets. A table you never want to leave.</p><span class="text-link">Explore Italy & Europe <span aria-hidden="true">↗</span></span></div></a></article>
    <div class="feature-side"><article class="feature small"><a href="/disney-trips/">{image('disney','Cinderella Castle at Walt Disney World')}<div class="caption"><span class="eyebrow">A little wonder, together</span><h3>Disney dreams</h3><p>Imagine the moments your family will remember.<span class="round-arrow" aria-hidden="true">↗</span></p></div></a></article>
    <article class="feature small"><a href="/cruises/">{image('cruise','A cruise ship on blue water beside a green coastline')}<div class="caption"><span class="eyebrow">A different kind of horizon</span><h3>Life at sea</h3><p>New shores, sea air, and time to enjoy the journey.<span class="round-arrow" aria-hidden="true">↗</span></p></div></a></article></div></div>
    <div class="custom-trip"><div><h3>Something else on your mind?</h3><p>You don’t need a finished itinerary to start a conversation.</p></div>{link('Share your trip idea','/plan-your-trip/?trip=Something%20else')}</div></div></section>
    <section class="why section"><div class="wrap"><div><span class="eyebrow">A person behind the planning</span><h2>Your trip deserves more than another open tab.</h2><p class="lead">Meet Sarah: an Iowa-based travel consultant with two decades of customer service experience and a love for adventures shared with the people who matter.</p></div><div>
    <div class="why-item"><span class="num">01</span><div><h3>A real conversation</h3><p>Start with your interests and your questions. You can contact Sarah directly by email or phone.</p></div></div>
    <div class="why-item"><span class="num">02</span><div><h3>A thoughtful starting point</h3><p>Share the details that matter to you: your dates, your travelers, and the kind of trip you have in mind.</p></div></div>
    <div class="why-item"><span class="num">03</span><div><h3>Room for your kind of adventure</h3><p>From small escapes to big ideas, begin with the experiences you want to share.</p></div></div></div></div></section>
    <section class="section"><div class="wrap"><span class="eyebrow">From a daydream to a conversation</span><h2>A simple place to begin.</h2><div class="steps"><div class="step"><div class="number">01</div><h3>Share your idea</h3><p>Tell Sarah where you’d like to go, when you might travel, and who’s coming along. It’s okay if you’re still exploring.</p></div><div class="step"><div class="number">02</div><h3>Ask your questions</h3><p>Discuss your priorities, budget, and the travel-planning help you’re looking for directly with Sarah.</p></div><div class="step"><div class="number">03</div><h3>Agree on the next step</h3><p>Ask Sarah to confirm available services, any fees, and the booking process before making a commitment.</p></div></div><p class="process-foot">An enquiry starts a conversation. It does not reserve a trip or make a booking.</p></div></section>
    <section class="about-section section"><div class="wrap about-grid"><figure class="about-visual">{image('family','Sarah Harry with her husband and daughter')}<figcaption>Adventures are better with the ones you love.</figcaption></figure><div class="about-copy"><span class="eyebrow">Meet your travel consultant</span><h2>Hi, I’m Sarah.<br>I’m glad you’re here.</h2><p>After two decades in customer service, I took the leap into travel. I’m excited to help you begin planning your next journey.</p><p>I’m based in Iowa and work as an independent travel consultant through Archer Travel. At home, life includes my supportive husband, my daughter, and our four Pomsky dogs.</p><p>I believe in enjoying the small and big adventures with the people you love.</p><div class="signature">Sarah</div>{link('A little more about me','/about/')}</div></div></section>
    <section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Notes for the journey</span><h2>The Travel Journal</h2></div><div>{link('Explore all stories','/blog/')}</div></div><div class="journal-grid">{journal_cards()}</div></div></section>{cta()}'''
    page('/','Personal travel planning with Sarah Harry','Travel inspiration, thoughtful trip ideas, and a personal conversation with Sarah Harry, an Iowa-based independent travel consultant through Archer Travel.',content)

def themed(route, title, eyebrow, heading, intro, asset, alt, leadheading, lead, notes, journal_slug, trip):
    relevant = next(a for a in ARTICLES if a['slug']==journal_slug)
    items=''.join(f'<li><strong>{esc(h)}</strong>{esc(t)}</li>' for h,t in notes)
    content=f'''<section class="page-hero"><div class="page-hero-copy"><div class="breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>Travel inspiration</span></div><span class="eyebrow">{eyebrow}</span><h1>{heading}</h1><p>{intro}</p>{button('Share This Trip Idea','/plan-your-trip/?trip='+quote(trip))}</div><figure>{image(asset,alt,eager=True)}</figure></section>
    <section class="section"><div class="wrap content-two"><div><span class="eyebrow">Imagine your version</span><h2>{leadheading}</h2><p>{lead}</p><p class="note">This page is travel inspiration. Ask Sarah which planning and booking services are currently available for your trip.</p>{link('Start with a conversation','/plan-your-trip/?trip='+quote(trip))}</div><div><h3>A few things to think about</h3><ul class="list-notes">{items}</ul></div></div></section>
    <section class="about-section section"><div class="wrap content-two"><div><span class="eyebrow">Read before you roam</span><h2>{esc(relevant['title'])}</h2><p>A little preparation can make your next conversation more useful. Explore Sarah’s journal, then bring your questions.</p>{link('Read the journal article','/post/'+journal_slug+'/')}</div><div>{image(relevant['slug'],'Travel photograph from the original journal article')}</div></div></section>{cta('Have your own version in mind?','Tell Sarah what you’re imagining and ask about the possibilities.')}'''
    page(route,title,intro,content)

def about():
    content=f'''<section class="page-hero"><div class="page-hero-copy"><span class="eyebrow">The person behind Travel With Sarah</span><h1>Big adventures.<br>A personal beginning.</h1><p>I’m Sarah Harry, an Iowa-based independent travel consultant through Archer Travel. I’m glad your next adventure brought you here.</p>{button('Let’s Talk About Your Trip','/plan-your-trip/')}</div><figure>{image('family','Sarah Harry with her husband and daughter',eager=True)}</figure></section>
    <section class="section"><div class="wrap content-two"><div><span class="eyebrow">Hello from Iowa</span><h2>A new chapter,<br>a familiar love of people.</h2><p>After two decades in customer service, I took the leap to become a travel agent. I’m excited to help you begin planning journeys and explore the places you’ve been dreaming about.</p><p>My husband has supported this change, and my daughter is right there cheering me on. We also share our home with four Pomsky dogs, who bring plenty of adventures of their own.</p><p>Travel With Sarah is my public-facing travel brand. I work independently through Archer Travel.</p></div><div><span class="eyebrow">What matters to me</span><h2>Enjoy the adventures.<br>Share the memories.</h2><p>My outlook is simple: enjoy the small and big adventures with the people you love.</p><p>Whether your idea is a family trip, a cruise, or time to discover somewhere new, tell me what matters most to you. A conversation is a good first step.</p><div class="signature serif">Sarah</div><p class="note">Have a question about how I work? Ask me directly about current services, fees, and booking arrangements.</p>{link('Contact Sarah','/contact/')}</div></div></section>{cta()}'''
    page('/about/','About Sarah Harry','Meet Sarah Harry, the Iowa-based independent travel consultant through Archer Travel behind Travel With Sarah.',content,'AboutPage')

def plan():
    field=lambda id,label,type='text',attrs='',optional=False: f'''<div class="field"><label for="{id}">{label}{' <span class="optional">(optional)</span>' if optional else ''}</label><input id="{id}" name="{id}" type="{type}" {attrs} aria-describedby="{id}-error"><p id="{id}-error" class="error" hidden></p></div>'''
    content=f'''<section class="plain-hero"><div class="wrap"><span class="eyebrow">Your idea is enough to get started</span><h1>Let’s talk about your next trip.</h1><p>A destination you love, a date on the calendar, or just a feeling. Share what you have in mind with Sarah.</p></div></section>
    <section class="section"><div class="wrap planning-layout"><aside class="planning-aside">{image('sarah','Sarah with her daughter','portrait-small')}<h2>A note to Sarah.</h2><p>You don’t need all the answers. Add what you know, and leave the rest open.</p><div class="aside-line"><span class="eyebrow">Prefer a conversation?</span><p><a href="tel:+15636908606">(563) 690-8606</a><br><a class="contact-email" href="mailto:{EMAIL}">{EMAIL}</a></p></div><div class="aside-line"><h3>What happens next?</h3><p>Review your enquiry, open the prepared email, and send it to Sarah. She can then discuss your trip and confirm the next steps with you.</p><p>An enquiry does not reserve travel. Ask Sarah about services, fees, availability, and booking terms.</p></div></aside>
    <div class="form-panel"><h2>A few details about your idea.</h2><p class="form-intro">Name and email are required. Everything else can wait.</p><noscript><p class="note">To use this form, enable JavaScript. You can also <a href="mailto:{EMAIL}">email Sarah directly</a> or call (563) 690-8606.</p></noscript><div id="form-errors" class="error-summary" role="alert" hidden></div>
    <form id="trip-form" novalidate><div class="form-grid">{field('name','Your name',attrs='required autocomplete="name" maxlength="100"')}{field('email','Email address','email',attrs='required autocomplete="email" maxlength="254"')}
    <div class="field"><label for="tripType">Trip type <span class="optional">(optional)</span></label><select id="tripType" name="tripType"><option value="">Still exploring</option>Disney</option><option>Cruise</option><option>Italy / Europe</option><option>Something else</option></select></div>
    {field('destination','Destination',attrs='placeholder="A place, a region, or open to ideas" maxlength="150"',optional=True)}{field('departureDate','Approximate departure date','date',optional=True)}
    <div class="field"><label for="flexibility">How flexible are your dates?</label><select id="flexibility" name="flexibility"><option>Not decided yet</option><option>Fixed dates</option><option>A few days flexible</option><option>Flexible by a few weeks</option><option>Open to different months</option></select></div>
    {field('travelers','Number of travelers','number',attrs='min="1" max="100" step="1" inputmode="numeric" placeholder="Including children"',optional=True)}
    <div class="field"><label for="budget">Total trip budget, USD <span class="optional">(optional)</span></label><select id="budget" name="budget"><option value="">Not decided yet</option><option>Under $2,000</option><option>$2,000–$5,000</option><option>$5,000–$10,000</option><option>$10,000–$20,000</option><option>$20,000+</option></select><p class="help">Your own planning range, not a trip quote.</p></div>
    {field('phone','Phone number','tel',attrs='autocomplete="tel" maxlength="40"',optional=True)}
    <div class="field full"><label for="notes">What would make this trip special? <span class="optional">(optional)</span></label><textarea id="notes" name="notes" maxlength="1200" rows="4" placeholder="A celebration, favorite activities, places you’d love to see…"></textarea><p class="help">Up to 1,200 characters. Please don’t include passport, payment, or sensitive personal details.</p></div></div>
    <p class="form-privacy">This form prepares an email on your device. Your details are shared with Sarah when you send that email from your email app. Nothing is booked by completing this form.</p><button class="button" type="submit">Review My Enquiry{ARROW}</button></form>
    <section id="enquiry-ready" class="enquiry-ready" tabindex="-1" aria-labelledby="enquiry-heading" hidden><span class="eyebrow">One more step</span><h3 id="enquiry-heading">Your enquiry is ready.</h3><p>It hasn’t been sent yet. Check the details below, then open your email draft and send it to Sarah. If an email app doesn’t open, copy the enquiry and email it to <a class="contact-email" href="mailto:{EMAIL}">{EMAIL}</a>.</p><pre id="enquiry-text"></pre><div class="enquiry-actions"><a id="email-draft" class="button" href="mailto:{EMAIL}">Open Email Draft{ARROW}</a><button class="button outline" id="copy-enquiry" type="button">Copy Enquiry</button></div><p id="copy-status" class="status" role="status" aria-live="polite"></p></section></div></div></section>'''
    page('/plan-your-trip/','Plan Your Trip','Share your destination ideas, approximate dates, travelers, and questions with Sarah Harry. Prepare a personal trip-planning enquiry.',content)

def contact():
    faqs=[('Do I need to know where I want to go?','No finished itinerary is needed to start an enquiry. Share the places or experiences you are considering, or tell Sarah you are still exploring.'),('What should I include in my enquiry?','Your name and email, a trip idea, approximate dates, and who is traveling are a useful starting point. A budget range and trip notes are optional.'),('Does submitting an enquiry book my trip?','No. The enquiry form prepares an email for you to send. It does not make a reservation or take a payment. Discuss available services and booking arrangements with Sarah directly.'),('Does Sarah charge a planning fee?','Ask Sarah to confirm whether fees apply to your trip and what they cover before you agree to any services. No fee schedule is published here.'),('Can I ask about Disney, Carnival cruises, or Europe?','Yes, you can share those interests with Sarah. These are themes featured on her existing website. Sarah will need to confirm which planning and booking services are currently available.'),('Where is Sarah based?','Sarah is based in Iowa and works as an independent travel consultant through Archer Travel. Ask her directly about service availability for your location.'),('What about cancellations, travel insurance, or booking terms?','Ask Sarah for the policies and supplier terms that apply to your specific trip before booking. Terms can depend on the travel provider and booking arrangements.')]
    details=''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in faqs)
    content=f'''<section class="plain-hero"><div class="wrap"><span class="eyebrow">A conversation, not a commitment</span><h1>Good trips start with good questions.</h1><p>Share your idea, ask what’s possible, or simply say hello. Here’s how to reach Sarah.</p></div></section><section class="section"><div class="wrap content-two"><div><h2>Let’s talk travel.</h2><div class="contact-box"><h3>Email Sarah</h3><p><a href="mailto:{EMAIL}">{EMAIL}</a></p></div><div class="contact-box"><h3>Call Sarah</h3><p><a href="tel:+15636908606">(563) 690-8606</a></p></div><div class="contact-box"><h3>Have a trip in mind?</h3><p>A few details are all you need to begin.</p><br>{button('Plan My Trip','/plan-your-trip/')}</div><p class="note">Travel With Sarah is Sarah Harry’s travel brand. Sarah is an independent travel consultant through Archer Travel.</p></div><div class="faq"><span class="eyebrow">Before you begin</span><h2>A few helpful answers.</h2>{details}</div></div></section>{cta()}'''
    page('/contact/','Contact Sarah & FAQs','Contact Sarah Harry by email or phone, and find answers about starting a trip enquiry with Travel With Sarah.',content,'ContactPage')

def journal():
    content=f'''<section class="plain-hero"><div class="wrap"><span class="eyebrow">Curiosity is a good travel companion</span><h1>Notes for the journey.</h1><p>Destination ideas, useful preparation, and a little inspiration from Sarah’s Travel Journal.</p></div></section><section class="section"><div class="wrap"><div class="journal-tools" role="group" aria-label="Filter journal articles"><button class="filter" data-filter="all" aria-pressed="true">All stories</button><button class="filter" data-filter="destinations" aria-pressed="false">Destination ideas</button><button class="filter" data-filter="packing" aria-pressed="false">Packing</button><button class="filter" data-filter="budget" aria-pressed="false">Budget</button></div><p id="journal-status" class="muted" role="status" aria-live="polite">3 articles shown</p><div class="journal-grid">{journal_cards()}</div></div></section>{cta('Inspired by something you’ve read?','Bring that idea to your conversation with Sarah.')}'''
    page('/blog/','Travel Journal','Explore Sarah Harry’s original travel articles on packing, destination inspiration, and traveling on a budget.',content,'CollectionPage')
    for a in ARTICLES:
        blocks=''.join(f'<{b["tag"]}>{esc(b["text"])}</{b["tag"]}>' for b in a['blocks'])
        content=f'''<header class="article-head"><div class="wrap"><div class="breadcrumb"><a href="/blog/">Travel Journal</a><span aria-hidden="true">/</span><span>Sarah’s stories</span></div><span class="eyebrow">The Travel Journal</span><h1>{esc(a['title'])}</h1><p class="article-meta">By Sarah Harry · September 11, 2026</p></div></header><section class="section" style="padding-top:15px"><div class="wrap article-layout"><article class="article-body" aria-label="{esc(a['title'],quote=True)}">{image(a['slug'],'Original photograph from Sarah’s '+a['title']+' article','article-picture',True)}{blocks}<p>{link('Back to all stories','/blog/')}</p></article><aside class="article-aside"><span class="eyebrow">An idea for your next trip?</span><h2>Let’s start there.</h2><p>Share what caught your imagination. Ask Sarah about planning possibilities for your own journey.</p>{button('Plan My Trip','/plan-your-trip/')}</aside></div></section>{cta()}'''
        page('/post/'+a['slug']+'/',a['title'],a['blocks'][0]['text'][:155],content,'Article')

def redirect(source,target):
    path=DIST/source.strip('/')/'index.html';path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(f'<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url={target}"><link rel="canonical" href="{SITE["canonical_origin"]}{target}"><title>Travel With Sarah</title></head><body><p>This page has moved. <a href="{target}">Continue to Travel With Sarah</a>.</p></body></html>')

def main():
    home();about();plan();contact();journal()
    themed('/disney-trips/','Disney Trip Inspiration','For your family’s next chapter','A little magic.<br>A lot to look forward to.','Imagine a trip filled with shared moments, familiar characters, and a little wonder. Start with the Disney experiences your family is dreaming about.','disney','Cinderella Castle at Walt Disney World','What does magic look like for your family?','A first visit, a return to a favorite park, or a celebration together: your starting point is personal. Think about the pace you enjoy and the experiences that matter most. Bring those ideas to a conversation with Sarah.',[('Your kind of park day','Favorite characters, attractions, shows, and the moments you would most like to share.'),('A pace that suits everyone','Travelers’ ages, rest days, and how much time you would like to spend exploring.'),('The bigger picture','Approximate dates, accommodation preferences, transportation, and an overall budget.')],'essential-packing-tips-for-your-next-adventure','Disney')
    themed('/cruises/','Cruise Inspiration','Time to follow a different horizon','More sea air.<br>More possibilities.','An open horizon, a new port, and the pleasure of the journey itself. Explore the idea of a cruise, including the Carnival theme featured on Sarah’s website.','cruise','A cruise ship in blue water','Let the journey be part of the trip.','Some travelers picture quiet deck time. Others imagine family activities or discovering a new port. Think about what you want your days at sea to feel like, and ask Sarah about current planning possibilities.',[('The itinerary','Regions you would like to explore, preferred departure ports, and how long you want to be away.'),('Life onboard','Your travel companions, cabin preferences, activities, and the balance between relaxing and exploring.'),('What’s included','Ask about the specific sailing’s inclusions, extra costs, deposits, and cancellation terms before booking.')],'how-to-travel-on-a-budget-tips-and-tricks','Cruise')
    themed('/italy-europe/','Italy & Europe Inspiration','Places worth taking your time with','A slower afternoon.<br>A bigger story.','From the streets of Rome to the canals of Venice, Italy invites you to notice the details. Explore a European trip shaped by the places that draw you in.','italy','Positano’s hillside buildings overlooking the Mediterranean','Leave a little room for discovery.','A city filled with history, a coastal town, or a few places connected into one journey. Begin with what interests you: food, art, architecture, or simply a change of pace. Sarah’s website features Italy as a source of inspiration.',[('Your places and priorities','A few must-see stops, experiences you enjoy, and places where you would like extra time.'),('The rhythm of your trip','One destination or several, relaxed days or busy ones, and how often you want to move between places.'),('Your starting details','Approximate dates, departure city, travel companions, and the budget you would like to discuss.')],'top-10-must-see-destinations-for-travelers','Italy / Europe')
